{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MapleMonk.zouk_bbf_store_level` AS WITH config AS ( SELECT 0.60 AS Sales_Weight, 0.10 AS AOV_Weight, 0.10 AS Bulk_Weight, 0.10 AS Repeat_Weight, 0.10 AS NonDiscount_Weight, 1 AS Bulk_Orders_Required, 1.00 AS NonDiscount_Threshold_Pct, 20000.0 AS Bulk_Order_Cutoff ), store_master AS ( SELECT SAFE_CAST(Location_ID AS INT64) AS location_id, Store_Code, Store_Name FROM `MapleMonk.Zouk_EBO_Store_Master` QUALIFY ROW_NUMBER() OVER (PARTITION BY SAFE_CAST(Location_ID AS INT64) ORDER BY Store_Code) = 1 ), base AS ( SELECT DATE(s.order_timestamp) AS Date, DATE_TRUNC(DATE(s.order_timestamp), WEEK(MONDAY)) AS Week_Start, DATE_TRUNC(DATE(s.order_timestamp), MONTH) AS Month, sm.Store_Code, sm.Store_Name, s.ORDER_ID, s.TOTAL_SALES, s.DISCOUNT, s.shopify_new_customer_flag FROM `MapleMonk.zouk_SHOPIFY_FACT_ITEMS` s LEFT JOIN store_master sm ON s.location_id = sm.location_id WHERE s.FINAL_MARKETPLACE = \'EBO\' AND LOWER(IFNULL(s.order_status, \'\')) NOT LIKE \'%cancel%\' ), order_level AS ( SELECT Week_Start, Store_Code, ORDER_ID, SUM(TOTAL_SALES) AS Order_Value, MAX(shopify_new_customer_flag) AS new_customer_flag FROM base WHERE Store_Code IS NOT NULL GROUP BY Week_Start, Store_Code, ORDER_ID ), weekly_store_agg AS ( SELECT Week_Start, Store_Code, Store_Name, SUM(TOTAL_SALES) AS Total_Sales, COUNT(DISTINCT ORDER_ID) AS Total_Orders, SUM(CASE WHEN IFNULL(DISCOUNT, 0) = 0 THEN TOTAL_SALES ELSE 0 END) AS Non_Discounted_Sales FROM base WHERE Store_Code IS NOT NULL GROUP BY Week_Start, Store_Code, Store_Name ), bulk_orders_agg AS ( SELECT ol.Week_Start, ol.Store_Code, COUNT(DISTINCT ol.ORDER_ID) AS Bulk_Orders FROM order_level ol, config c WHERE ol.Order_Value >= c.Bulk_Order_Cutoff GROUP BY ol.Week_Start, ol.Store_Code ), repeat_orders_agg AS ( SELECT Week_Start, Store_Code, COUNT(DISTINCT ORDER_ID) AS Repeat_Orders FROM order_level WHERE new_customer_flag = \'Repeat\' GROUP BY Week_Start, Store_Code ), weekly_targets AS ( SELECT DATE_TRUNC(Date, WEEK(MONDAY)) AS Week_Start, Store_Code, SUM(Target) AS Week_Target FROM `MapleMonk.zouk_store_target_vs_achievement` WHERE Store_Code IS NOT NULL GROUP BY Week_Start, Store_Code ), monthly_country_agg AS ( SELECT Month, SAFE_DIVIDE(SUM(TOTAL_SALES), COUNT(DISTINCT ORDER_ID)) AS Country_Monthly_AOV FROM base WHERE Store_Code IS NOT NULL GROUP BY Month ), date_spine AS ( SELECT DISTINCT Week_Start FROM weekly_store_agg UNION DISTINCT SELECT DISTINCT Week_Start FROM weekly_targets ), full_grid AS ( SELECT d.Week_Start, sm.Store_Code, sm.Store_Name FROM date_spine d CROSS JOIN store_master sm ), joined AS ( SELECT fg.Week_Start, fg.Store_Code, fg.Store_Name, IFNULL(wsa.Total_Sales, 0) AS Total_Sales, IFNULL(wsa.Total_Orders, 0) AS Total_Orders, IFNULL(wsa.Non_Discounted_Sales, 0) AS Non_Discounted_Sales, IFNULL(boa.Bulk_Orders, 0) AS Bulk_Orders, IFNULL(roa.Repeat_Orders, 0) AS Repeat_Orders, IFNULL(wt.Week_Target, 0) AS Sales_Target FROM full_grid fg LEFT JOIN weekly_store_agg wsa ON fg.Week_Start = wsa.Week_Start AND fg.Store_Code = wsa.Store_Code LEFT JOIN bulk_orders_agg boa ON fg.Week_Start = boa.Week_Start AND fg.Store_Code = boa.Store_Code LEFT JOIN repeat_orders_agg roa ON fg.Week_Start = roa.Week_Start AND fg.Store_Code = roa.Store_Code LEFT JOIN weekly_targets wt ON fg.Week_Start = wt.Week_Start AND fg.Store_Code = wt.Store_Code ), metrics AS ( SELECT j.*, SAFE_DIVIDE(j.Total_Sales, j.Total_Orders) AS AOV, mca.Country_Monthly_AOV AS AOV_Target, SAFE_DIVIDE(j.Non_Discounted_Sales, j.Total_Sales) AS Non_Discounted_Pct, MAX(j.Repeat_Orders) OVER (PARTITION BY j.Week_Start) AS Repeat_Target FROM joined j LEFT JOIN monthly_country_agg mca ON DATE_TRUNC(j.Week_Start, MONTH) = mca.Month ) SELECT m.Week_Start, m.Store_Code, m.Store_Name, m.Total_Sales, m.Sales_Target, ROUND(LEAST(SAFE_DIVIDE(m.Total_Sales, m.Sales_Target), 1.0) * c.Sales_Weight * 100, 2) AS Sales_Target_Points, ROUND(m.AOV, 2) AS AOV, ROUND(m.AOV_Target, 2) AS AOV_Target, ROUND(LEAST(SAFE_DIVIDE(m.AOV, m.AOV_Target), 1.0) * c.AOV_Weight * 100, 2) AS AOV_Target_Points, m.Bulk_Orders, CAST(c.Bulk_Orders_Required AS FLOAT64) AS Bulk_Orders_Target, IF(m.Bulk_Orders >= c.Bulk_Orders_Required, c.Bulk_Weight * 100, 0.0) AS Bulk_Orders_Target_Points, m.Repeat_Orders AS Repeat_Customers, m.Repeat_Target AS Repeat_Customers_Target, ROUND(LEAST(SAFE_DIVIDE(m.Repeat_Orders, m.Repeat_Target), 1.0) * c.Repeat_Weight * 100, 2) AS Repeat_Customers_Target_Points, ROUND(m.Non_Discounted_Pct * 100, 2) AS Non_Discounted_Sales_Pct, ROUND(c.NonDiscount_Threshold_Pct * 100, 2) AS Non_Discounted_Sales_Target, ROUND(LEAST(SAFE_DIVIDE(m.Non_Discounted_Pct, c.NonDiscount_Threshold_Pct), 1.0) * c.NonDiscount_Weight * 100, 2) AS Non_Discounted_Sales_Target_Points, ROUND( LEAST(SAFE_DIVIDE(m.Total_Sales, m.Sales_Target), 1.0) * c.Sales_Weight * 100 + LEAST(SAFE_DIVIDE(m.AOV, m.AOV_Target), 1.0) * c.AOV_Weight * 100 + IF(m.Bulk_Orders >= c.Bulk_Orders_Required, c.Bulk_Weight * 100, 0.0) + LEAST(SAFE_DIVIDE(m.Repeat_Orders, m.Repeat_Target), 1.0) * c.Repeat_Weight * 100 + LEAST(SAFE_DIVIDE(m.Non_Discounted_Pct, c.NonDiscount_Threshold_Pct), 1.0) * c.NonDiscount_Weight * 100 , 2) AS Overall_Target_Points FROM metrics m CROSS JOIN config c ; CREATE OR REPLACE TABLE `MapleMonk.zouk_bbf_staff_level` AS WITH config AS ( SELECT 0.60 AS Sales_Weight, TRUE AS Count_Sales_Across_Stores ), staff_targets_sheet AS ( SELECT Start_Date, End_Date, Employee_name, store_name, targets FROM `MapleMonk.Zouk_Sheet1` ), staff_targets_parsed AS ( SELECT COALESCE( SAFE.PARSE_DATE(\'%d/%m/%Y\', TRIM(CAST(Start_Date AS STRING))), SAFE.PARSE_DATE(\'%d-%m-%Y\', TRIM(CAST(Start_Date AS STRING))), SAFE.PARSE_DATE(\'%d-%b-%y\', TRIM(CAST(Start_Date AS STRING))), SAFE.PARSE_DATE(\'%Y-%m-%d\', TRIM(CAST(Start_Date AS STRING))) ) AS Period_Start, COALESCE( SAFE.PARSE_DATE(\'%d/%m/%Y\', TRIM(CAST(End_Date AS STRING))), SAFE.PARSE_DATE(\'%d-%m-%Y\', TRIM(CAST(End_Date AS STRING))), SAFE.PARSE_DATE(\'%d-%b-%y\', TRIM(CAST(End_Date AS STRING))), SAFE.PARSE_DATE(\'%Y-%m-%d\', TRIM(CAST(End_Date AS STRING))) ) AS Period_End, TRIM(REGEXP_REPLACE(Employee_name, r\'\s+\', \' \')) AS Staff_Name, UPPER(TRIM(REGEXP_REPLACE(Employee_name, r\'\s+\', \' \'))) AS Staff_Key, TRIM(REGEXP_REPLACE(store_name, r\'\s+\', \' \')) AS Store_Name, UPPER(TRIM(REGEXP_REPLACE(store_name, r\'\s+\', \' \'))) AS Store_Key, SAFE_CAST(REPLACE(REPLACE(TRIM(CAST(targets AS STRING)), \',\', \'\'), \'₹\', \'\') AS FLOAT64) AS Sales_Target FROM staff_targets_sheet WHERE NULLIF(TRIM(Employee_name), \'\') IS NOT NULL ), staff_targets_dedup AS ( SELECT * FROM staff_targets_parsed WHERE Period_Start IS NOT NULL AND Period_End IS NOT NULL AND Period_End >= Period_Start AND Sales_Target IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY Period_Start, Period_End, Staff_Key, Store_Key ORDER BY 1) = 1 ), store_master AS ( SELECT Store_Code, UPPER(TRIM(REGEXP_REPLACE(Store_Name, r\'\s+\', \' \'))) AS Store_Key FROM `MapleMonk.Zouk_EBO_Store_Master` QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(REGEXP_REPLACE(Store_Name, r\'\s+\', \' \'))) ORDER BY Store_Code) = 1 ), targets AS ( SELECT t.Period_Start, t.Period_End, t.Staff_Key, IF(c.Count_Sales_Across_Stores, \'ALL\', t.Store_Key) AS Scope_Key, ARRAY_AGG(t.Staff_Name ORDER BY t.Sales_Target DESC LIMIT 1)[SAFE_OFFSET(0)] AS Staff_Name, ARRAY_AGG(t.Store_Name IGNORE NULLS ORDER BY t.Sales_Target DESC LIMIT 1)[SAFE_OFFSET(0)] AS Store_Name, ARRAY_AGG(t.Store_Key IGNORE NULLS ORDER BY t.Sales_Target DESC LIMIT 1)[SAFE_OFFSET(0)] AS Home_Store_Key, SUM(t.Sales_Target) AS Sales_Target FROM staff_targets_dedup t CROSS JOIN config c GROUP BY t.Period_Start, t.Period_End, t.Staff_Key, Scope_Key ), base AS ( SELECT DATE(s.order_timestamp) AS Order_Date, UPPER(TRIM(REGEXP_REPLACE(s.Staff_Name, r\'\s+\', \' \'))) AS Staff_Key, UPPER(TRIM(REGEXP_REPLACE(s.Source, r\'\s+\', \' \'))) AS Store_Key, s.ORDER_ID, s.TOTAL_SALES FROM `MapleMonk.zouk_SHOPIFY_FACT_ITEMS` s WHERE s.Marketplace_Segments = \'OFFLINE\' AND LOWER(IFNULL(s.order_status, \'\')) NOT LIKE \'%cancel%\' AND NULLIF(TRIM(s.Staff_Name), \'\') IS NOT NULL ), joined AS ( SELECT t.Period_Start, t.Period_End, t.Staff_Key, t.Scope_Key, t.Staff_Name, t.Store_Name, t.Home_Store_Key, t.Sales_Target, IFNULL(SUM(b.TOTAL_SALES), 0) AS Total_Sales, COUNT(DISTINCT b.ORDER_ID) AS Total_Orders FROM targets t CROSS JOIN config c LEFT JOIN base b ON b.Staff_Key = t.Staff_Key AND b.Order_Date BETWEEN t.Period_Start AND t.Period_End AND (c.Count_Sales_Across_Stores OR b.Store_Key = t.Home_Store_Key) GROUP BY t.Period_Start, t.Period_End, t.Staff_Key, t.Scope_Key, t.Staff_Name, t.Store_Name, t.Home_Store_Key, t.Sales_Target ) SELECT j.Period_Start AS Start_Date, j.Period_End AS End_Date, DATE_TRUNC(j.Period_Start, WEEK(MONDAY)) AS Week_Start, j.Period_End < CURRENT_DATE() AS Period_Complete, sm.Store_Code, j.Store_Name, j.Staff_Name, j.Total_Orders, j.Total_Sales, j.Sales_Target, CAST(ROUND(SAFE_DIVIDE(CAST(j.Total_Sales AS NUMERIC) * 100, CAST(j.Sales_Target AS NUMERIC)), 2) AS FLOAT64) AS Sales_Achievement_Pct, CAST(ROUND(SAFE_DIVIDE(CAST(LEAST(j.Total_Sales, j.Sales_Target) AS NUMERIC) * CAST(c.Sales_Weight * 100 AS NUMERIC), CAST(j.Sales_Target AS NUMERIC)), 2) AS FLOAT64) AS Sales_Target_Points FROM joined j CROSS JOIN config c LEFT JOIN store_master sm ON sm.Store_Code IS NOT NULL AND sm.Store_Key = j.Home_Store_Key ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            